object BibleNewsData {
    val newsList = listOf(
        BibleNews(1, "O TRÁGICO FIM DA CONCUBINA!", "O levita e o terror em Gibeá. Uma história chocante de abuso, assassinato e uma guerra que quase exterminou a tribo de Benjamim. Você não vai acreditar no que ele fez com o corpo!", "Juízes", 19, 29, "https://picsum.photos/seed/news_concubina/600/400"),
        BibleNews(2, "O ATAQUE DAS URSAS ASSASSINAS!", "Zombaram da careca do profeta e o pior aconteceu. Eliseu amaldiçoou os jovens e duas ursas saíram da floresta, despedaçando 42 deles! O que isso nos ensina sobre o respeito aos ungidos de Deus?", "2 Reis", 2, 23, "https://picsum.photos/seed/news_ursas/600/400"),
        BibleNews(3, "A MALDIÇÃO DE CAM!", "Noé bebeu demais, ficou nu em sua tenda, e seu filho Cam viu o que não devia. O resultado? Uma maldição que afetou gerações! Entenda o mistério por trás desse episódio sombrio.", "Gênesis", 9, 20, "https://picsum.photos/seed/news_cam/600/400"),
        BibleNews(4, "O MASSACRE DE ABIMELEQUE!", "O homem que matou 70 dos seus próprios irmãos sobre uma única pedra para tomar o poder. Uma história sangrenta de traição, ambição e uma morte vergonhosa por uma pedra de moinho!", "Juízes", 9, 5, "https://picsum.photos/seed/news_abimeleque/600/400"),
